// Isolation test (OS-12) — construct IndependenceLedger with its declared inputs and
// nothing else, then exercise every public operation. (Generated by new-object.py,
// rewritten for strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { IndependenceLedger, type Unit } from "../src/catalog/index.js";
import { inMemoryRecord } from "./catalog/in-memory-record.js";

// A Unit is an operation INPUT, not a constructor dependency, so the test names one
// directly rather than building it through UnitRegistry: an isolation test that needs
// a second class is not testing one class in isolation (OS-12).
const u = "u1" as Unit;

describe("IndependenceLedger in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    expect(() => new IndependenceLedger({} as never)).toThrow();
  });

  it("refuses a record that does not offer append and readAsOf (OS-1, a declared slot)", () => {
    expect(() => new IndependenceLedger({ record: {} as never })).toThrow();
  });

  it("declareIndependence answers differently when record differs", () => {
    const busy = inMemoryRecord();
    busy.noise();
    const a = new IndependenceLedger({ record: inMemoryRecord() }).declareIndependence(u, true, "HUMAN");
    const b = new IndependenceLedger({ record: busy }).declareIndependence(u, true, "HUMAN");
    expect(a).not.toEqual(b);
  });

  it("independenceAt answers differently when record differs", () => {
    const granted = inMemoryRecord();
    const at = new IndependenceLedger({ record: granted }).declareIndependence(u, true, "HUMAN").at;
    const other = inMemoryRecord();
    other.noise();
    const a = new IndependenceLedger({ record: granted }).independenceAt(u, at);
    const b = new IndependenceLedger({ record: other }).independenceAt(u, at);
    expect(a).not.toEqual(b);
  });
});
